/bin/bash -lc "cat > ./src/util/ordersApi.mjs <<'EOF'
/**
 * Normalizes the backend's order-list response into a flat object:
 *
 *   { orders, pages, total, onThisPage }
 *
 * The backend defines the list response (ReadableOrderList, which extends
 * ReadableList) with the fields:
 *   - orders:      List<ReadableOrder>  -> the list of orders
 *   - pageCount:   int                  -> the number of pages
 *   - totalRecords: long               -> the total number of records
 *   - itemsOnPage: int                 -> the number of records on this page
 *
 * Missing or non-finite values become an empty list or 0.
 */

function toNumber(value) {
  return Number.isFinite(value) ? value : 0;
}

export function normalizeOrderList(response) {
  const body = response && typeof response === 'object' ? response : {};

  return {
    orders: Array.isArray(body.orders) ? body.orders : [],
    pages: toNumber(body.pageCount),
    total: toNumber(body.totalRecords),
    onThisPage: toNumber(body.itemsOnPage)
  };
}
EOF
node --input-type=module -e \"
import { readFileSync } from 'node:fs';
const code = readFileSync('./src/util/ordersApi.mjs', 'utf8');
const mod = await import('data:text/javascript;base64,' + Buffer.from(code).toString('base64'));
const { normalizeOrderList } = mod;
console.log(JSON.stringify(normalizeOrderList({ orders: [{id:1},{id:2}], pageCount: 3, totalRecords: 17, itemsOnPage: 5, recordsFiltered: 9 })));
console.log(JSON.stringify(normalizeOrderList({ orders: null, pageCount: 0, totalRecords: 0, itemsOnPage: 0 })));
console.log(JSON.stringify(normalizeOrderList(undefined)));
console.log(JSON.stringify(normalizeOrderList(null)));
console.log(JSON.stringify(normalizeOrderList({ orders: 'x', pageCount: 'bad', totalRecords: null })));
console.log('export type:', typeof normalizeOrderList);
\""
